V["impactful_ids"] = ", ".join(r[0] for r in IMPACTFUL); V["unverified_ids"] = ", ".join(r[0] for r in UNVER)

def esc(t): return str(t).replace("|", "/").replace("\n", " ")
def matrix_md():
    out = ["# Audit compliance matrix (Ma trận tuân thủ)", "", "Paper: Fang et al., *Scaling Laws For Dense Retrieval*, SIGIR '24 (arXiv 2403.18684v2). Every statement about the paper cites a section, figure, table or equation; anything not verifiable is marked UNVERIFIED.", ""]
    out += ["| " + " | ".join(HEAD) + " |", "|" + "|".join(["---"] * len(HEAD)) + "|"]
    for r in ROWS: out.append("| " + " | ".join(esc(c) for c in r) + " |")
    out += ["", "## Counts by status", "", "| Status | Count |", "|---|---|"] + [f"| {s} | {COUNTS[s]} |" for s in ST] + [f"| **Total** | {len(ROWS)} |", "", "## Verdict per group (Phán quyết)", "", "| Group | Verdict | Why |", "|---|---|---|"]
    names = {"A": "A. Course brief", "B": "B. First assignment", "C": "C. Fidelity to the paper", "D": "D. Experimental hygiene"}
    out += [f"| {names[k]} | {VERD[k]} | {esc(VERD_WHY[k])} |" for k in "ABCD"]
    out += ["", "## DEVIATION-IMPACTFUL items", ""] + [f"- **{r[0]}**: {r[2]}. {r[5]} → {r[8]}" for r in IMPACTFUL]
    out += ["", "## UNVERIFIED items", ""] + [f"- **{r[0]}**: {r[2]}. {r[5]}" for r in UNVER]
    return "\n".join(out) + "\n"
def write_matrix(dst):
    import csv
    with open(os.path.join(dst, "AUDIT_COMPLIANCE_MATRIX.csv"), "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh); w.writerow(HEAD); w.writerows(ROWS)
    open(os.path.join(dst, "AUDIT_COMPLIANCE_MATRIX.md"), "w", encoding="utf-8").write(matrix_md())
if __name__ == "__main__":
    write_matrix(PKG); print(COUNTS, V["impactful_ids"], V["unverified_ids"])
